package com.lqq.supportflow.conversation.application;
import com.lqq.supportflow.conversation.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class SubmitCustomerMessageService { private final ConversationPort conversations; private final GenerationEventStore events; public SubmitCustomerMessageService(ConversationPort conversations,GenerationEventStore events){this.conversations=conversations;this.events=events;} @Transactional public Generation submit(Long tenantId,Long customerId,Long conversationId,String content,String idempotencyKey){if(!conversations.belongsTo(tenantId,customerId,conversationId))throw new IllegalArgumentException("conversation does not belong to customer");Generation generation=conversations.submit(tenantId,conversationId,content,idempotencyKey);events.append(generation.id(),"generation.queued","{\"status\":\"QUEUED\"}");return generation;}}
